package pflag

import "testing"

func TestHiddenVisitAllStop(t *testing.T) {
	fs := NewFlagSet("t", ContinueOnError)
	fs.Bool("a", false, "")
	fs.Bool("b", false, "")
	fs.Bool("c", false, "")
	n := 0
	fs.VisitAll(func(*Flag) bool { n++; return false })
	if n != 1 {
		t.Fatalf("visited %d flags after returning false, want 1", n)
	}
	n = 0
	fs.VisitAll(func(*Flag) bool { n++; return true })
	if n != 3 {
		t.Fatalf("visited %d flags, want 3", n)
	}
}
